(function(){
  if (typeof window.Stomp !== 'undefined' && typeof window.Stomp.over === 'function') return;
  var s = document.createElement('script');
  s.src = 'https://cdn.jsdelivr.net/npm/stompjs@2.3.3/lib/stomp.min.js';
  s.onload = function(){ console.info('Stomp.js loaded'); };
  s.onerror = function(){ console.warn('Failed to load Stomp.js from CDN'); };
  document.head.appendChild(s);
})();

